#!/usr/bin/env python3
"""Verify actual v13 Intake export capture using unchanged native media analysis."""
import argparse,json,os,pathlib,re
from datetime import datetime,timezone
import verify_arsenal_recordings as m
import verify_map_recording as prior
P=pathlib.Path(__file__).resolve().parents[1]
def main():
 p=argparse.ArgumentParser(description=__doc__)
 for key in ['executable','avi','mp4','wav','route-report','native-log','launch-evidence','report']:p.add_argument('--'+key,type=pathlib.Path,required=True)
 p.add_argument('--source-commit',required=True);a=p.parse_args();exe=a.executable.resolve();avi=a.avi.resolve();mp4=a.mp4.resolve();wav=a.wav.resolve();out=a.report.resolve()
 require=m.require;require(all(f.is_file() for f in [exe,avi,a.route_report,a.native_log,a.launch_evidence]),'Missing source evidence');require(not avi.is_relative_to(P) and not mp4.is_relative_to(P) and not wav.is_relative_to(P),'Keep media outside project')
 if hasattr(os,'sched_getaffinity'):os.sched_setaffinity(0,sorted(os.sched_getaffinity(0))[:8])
 out.parent.mkdir(parents=True,exist_ok=True);log=m.Log(out.with_suffix('.log'));build=prior.validate_build(exe.parent/'BUILD.json',exe,a.source_commit)
 receipt=json.loads(a.launch_evidence.read_text());cmd=receipt['command'];require(receipt['exit_code']==0 and receipt['source_commit']==a.source_commit and receipt['executable_sha256']==m.sha(exe),'Wrong launch identity/exit');require(cmd==receipt['observed_proc_cmdline'] and pathlib.Path(cmd[0]).resolve()==exe and receipt['cwd']=='/tmp' and receipt['observed_proc_cwd']==str(exe.parent),'Not the observed actual exported process');require(prior.command_value(cmd,'--fixed-fps')=='30' and prior.command_value(cmd,'--write-movie')==str(avi) and prior.command_value(cmd,'--log-file')==str(a.native_log.resolve()),'Wrong movie/log command');require(all(flag in cmd for flag in ['--v13-route-test','--v13-level-count=1','--campaign-level=pale_ward_01','--automated-input','--force-offscreen-draw','--use-heavy-weapons']),'Wrong v13 capture mode')
 route=json.loads(a.route_report.read_text());require(route['status']=='passed' and route['failures']==[] and route['levels_completed']==route['expected_levels']==1 and not route['editor_feature'] and pathlib.Path(route['executable']).resolve()==exe,'Not completed actual exported Intake');r=route['levels'][0];require(r['level']=='pale_ward_01' and r['completed'] and not r['secret_used'] and r['health']>0 and all(r['flags'].get(f,False) for f in ['local_power','surgical_credential','decon_clear']),'New Intake objectives/survival failed');require(all(r['weapon_shots'].get(w,0)>0 for w in ['pistol','shotgun','twin_shotgun']),'Capture must use accepted three guns');require(r.get('checkpoint_at_exit',False),'No checkpoint secured on captured route')
 text=a.native_log.read_text();require(not re.search(r'(^|\n)\s*(SCRIPT ERROR:|ERROR:|WARNING:)',text) and 'LEVELS_V13_ROUTE passed 1/1' in text and 'OpenGL API' in text and 'Movie Maker mode enabled' in text,'Native graphics/movie/clean-success log missing')
 originals={str(f.resolve()):m.record(f) for f in [exe,avi,a.route_report,a.native_log,a.launch_evidence]};source=m.video_info(m.probe(avi,log,True));require(source['format']['format_name']=='avi' and source['audio']['codec_name'].startswith('pcm_'),'Need original native PCM AVI');pcm=m.raw_pcm(avi,source['audio'],log);require(abs(pcm['seconds']-source['seconds'])<=m.TOLERANCE,'PCM/video duration mismatch');require(source['seconds']>=r['physics_seconds'] and source['seconds']-r['physics_seconds']<30,'Movie does not cover route');diversity=m.native_frame_diversity(avi,source['frames'],log)
 log.run(['ffmpeg','-hide_banner','-nostdin','-y','-i',avi,'-map','0:a:0','-vn','-sn','-dn','-c:a','copy',wav]);wd=m.probe(wav,log);wv,wa=m.streams(wd);require(not wv and len(wa)==1,'Wrong master streams');wp=m.raw_pcm(wav,wa[0],log,False);require(wp['native_pcm_payload_sha256']==pcm['native_pcm_payload_sha256'] and wp['native_pcm_payload_bytes']==pcm['native_pcm_payload_bytes'],'WAV is not exact original PCM')
 log.run(['ffmpeg','-hide_banner','-nostdin','-y','-threads','2','-i',avi,'-map','0:v:0','-map','0:a:0','-c:v','libx264','-threads','4','-preset','fast','-crf','16','-pix_fmt','yuv420p','-c:a','aac','-b:a','256k','-movflags','+faststart',mp4]);encoded=m.video_info(m.probe(mp4,log,True),source['frames']);require(encoded['video']['codec_name']=='h264' and encoded['audio']['codec_name']=='aac','Wrong delivery codecs');decoded=m.decoded_aac(mp4,encoded['audio'],log);require(abs(decoded['decoded_seconds']-pcm['seconds'])<=m.TOLERANCE,'AAC duration mismatch')
 for f,record in originals.items():require(m.sha(pathlib.Path(f))==record['sha256'],'Original source evidence mutated')
 result={'status':'passed','source_commit':a.source_commit,'export':build,'launch':m.record(a.launch_evidence),'route':{**m.record(a.route_report),'level':r},'native_video':source,'native_frame_diversity':diversity,'master_pcm':pcm,'master_wav':m.record(wav),'mp4':m.record(mp4),'original_inputs':originals,'helper':m.record(pathlib.Path(__file__)),'reused_analysis':m.record(pathlib.Path(m.__file__)),'processing':'Full native AVI video/audio; WAV exact PCM stream copy, full-length H264CRF16/AAC256k MP4 without trims/filters/gain/overlays. Lossy delivery codecs.','scope':'Actual exported automated physical Intake play with new objectives/checkpoint. Numeric media checks do not establish human visual/listening or20–25minute pacing acceptance.','verified_utc':datetime.now(timezone.utc).isoformat()};out.write_text(json.dumps(result,indent=2)+'\n');print('V13_RECORDING_OK',source['frames'],pcm['seconds'])
if __name__=='__main__':main()
